// 区块路径
const rootEntire = $self.address.entire
// 只截取自己和父节点，避免拖动位置后数据丢失
const cacheKeyPrefix = $self.address.segments.slice(-2).join(".")
// 翻译卡片设置持久化缓存的 key，这里没有拼接 cacheKeyPrefix 是因为这些翻译设置要在用户脚本中使用
const cacheKeyTranslateCardSettings = `translateCardSettings`

// 修复样式问题
$props({
  className: $self.props.name,
})
$effect(() => {
  const rootNode = document.querySelector(`.${$self.props.name}`)
  if (rootNode) {
    const element = rootNode.querySelector(
      ".ant-formily-item-feedback-layout-loose"
    )
    if (element) {
      element.style.marginBottom = 0
    }
  }
}, [])

// 展示设置对话框
$self.showSettingsDialog = () => {
  const settingsDialog = $self
    .query(`${rootEntire}.translateSettingsDialog`)
    .take()
  settingsDialog.setComponentProps({
    open: true,
  })
}

// 获取翻译设置信息
$self.getSettings = async () => {
  try {
    const res = await $chrome.storage.local.get(cacheKeyTranslateCardSettings)
    const settings = res[cacheKeyTranslateCardSettings]

    return settings || {}
  } catch (e) {
    $logger.info("获取缓存的翻译设置失败", e)
    return {}
  }
}

// 更新多领国设置
$self.updateSettings = async ({ settings }) => {
  try {
    await $chrome.storage.local.set({
      [cacheKeyTranslateCardSettings]: settings,
    })

    refreshTranslateCardTitle()
  } catch (e) {
    $logger.info("更新翻译设置失败", e)
  }
}

// 刷新翻译卡片标题
const refreshTranslateCardTitle = async () => {
  try {
    const settings = await $self.getSettings()
    const translateTitleText = $self
      .query(`${rootEntire}.headerDiv.headerLeftDiv.translateTitleText`)
      .take()
    const vendor = settings?.vendor
    if (vendor) {
      translateTitleText.value = `「${vendor}」翻译`
    } else {
      translateTitleText.value = "请先设置翻译厂商"
    }
  } catch (e) {
    $logger.info("获取缓存的翻译标题失败", e)
  }
}

$effect(() => {
  refreshTranslateCardTitle()
}, [])

