// 使用 AI API 进行翻译
const translateWithAI = async (settings, text) => {
  // 如果没有配置 apiKey 返回错误提示
  if (!settings.apiKey) {
    $message.error("请先在插件配置页面设置 apiKey")
    return null
  }

  try {
    const response = await fetch(settings.apiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${settings.apiKey}`,
      },
      body: JSON.stringify({
        model: settings.model,
        messages: [
          {
            role: "system",
            content:
              "你是一个专业的翻译助手，请将用户提供的文本翻译成中文。如果原文已经是中文，则翻译成英文。",
          },
          {
            role: "user",
            content: text,
          },
        ],
        stream: false,
      }),
    })

    if (!response.ok) {
      $message.error(`翻译失败: ${response.statusText}`)
      return null
    }

    const data = await response.json()
    return data.choices[0].message.content
  } catch (error) {
    $message.error(`翻译失败: ${error.message}`)
    return null
  }
}

// 通过百度获取原文语言类型
const getLan = (text) => {
  return fetch("https://fanyi.baidu.com/langdetect", {
    headers: {
      "content-type": "application/x-www-form-urlencoded",
    },
    body: `query=${encodeURIComponent(text)}`,
    method: "POST",
  })
    .then((res) => res.json())
    .then((res) => {
      if (res.error === 0) {
        return res.lan
      } else {
        $message.error(`自动检测当前语言失败 ${res.msg}`)
        return null
      }
    })
    .catch((e) => {
      $message.error("自动检测当前语言失败")
      return null
    })
}

// 通过百度翻译为目标语言
const getToLanguage = (from, text) => {
  let to = "zh"
  if (from === "zh") {
    to = "en"
  }
  return fetch("https://fanyi.baidu.com/transapi", {
    headers: {
      "content-type": "application/x-www-form-urlencoded",
    },
    body: `from=${from}&query=${encodeURIComponent(text)}&source=txt&to=${to}`,
    method: "POST",
  })
    .then((res) => res.json())
    .then((res) => {
      if (res.status === 0) {
        if (res.type === 2) {
          return res.data?.[0].dst
        } else if (res.type === 1) {
          const data = JSON.parse(res.result)
          const mean = data.content[0].mean
          const result = mean
            .map((item) => {
              const cont = Object.keys(item.cont).join("; ")

              if (item.pre) {
                return `${item.pre} ${cont}`
              } else {
                return cont
              }
            })
            .join("\n")
          return result
        } else {
          $message.error("未支持的翻译类型")
          return
        }
      } else {
        $message.error("翻译失败")
        return null
      }
    })
    .catch((e) => {
      $message.error("翻译失败")
      return null
    })
}

// 使用百度 API 进行翻译
const translateWithBaiDu = async (text) => {
  const lan = await getLan(text)
  if (!lan) {
    return null
  }

  const result = await getToLanguage(lan, text)
  return result
}

let lastText = null
const handleTranslate = async (e) => {
  const toLanguage = $self
    .query(`${$self.parent.address.entire}.toLanguage`)
    .take()

  const text = e.target.value
  if (!text) {
    toLanguage.value = ""
    return
  }
  if (text === lastText) {
    return
  }

  lastText = text

  const settings = await rootField.getSettings()
  let result = null
  if (settings.apiUrl) {
    result = await translateWithAI(settings, text)
  } else {
    result = await translateWithBaiDu(text)
  }

  if (!result) {
    toLanguage.value = ""
    return
  }

  toLanguage.value = result
}

$props({
  onChange: (e) => {
    const text = e.target.value
    if (!text) {
      const toLanguage = $self
        .query(`${$self.parent.address.entire}.toLanguage`)
        .take()
      toLanguage.value = ""
    }
  },
  onPressEnter: (e) => {
    e.preventDefault()

    handleTranslate(e)
  },
  onBlur: (e) => {
    handleTranslate(e)
  },
})

