  onChange: (value, option) => {
    const modelField = $self.query(`${parentEntire}.model`).take()
    const apiKeyField = $self.query(`${parentEntire}.apiKey`).take()

    if (option.apiUrl) {
      window.$test = $self
      modelField.visible = true
      apiKeyField.visible = true

      modelField.value = undefined
      apiKeyField.value = undefined
      modelField.dataSource = option.modelDatasource
    } else {
      modelField.visible = false
      apiKeyField.visible = false

      modelField.value = undefined
      apiKeyField.value = undefined
      modelField.dataSource = []
    }
  },
})

